// Doctor Calendar: month, week and day views beside the selected day's agenda, with an appointment drawer.
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Link } from 'react-router-dom'

import { ErrorState } from '../../components/shared/ViewState'
import { doctorWorkspaceApi, threePortalApi, type AppointmentDto, type DoctorScheduleDto } from '../../services/apiClient'
import { AppointmentDrawer } from './calendar/AppointmentDrawer'
import { DateStrip, DayTimeline, MonthGrid, WeekGrid } from './calendar/CalendarViews'
import { dayKey, formatLongDay, groupByDay, isActive, rangeTitle, shiftByView, startOfDay, workingHoursFor, type CalendarView } from './calendar/calendarUtils'
import '../../styles/doctor-calendar.css'

const views: { id: CalendarView; label: string }[] = [
  { id: 'month', label: 'Month' },
  { id: 'week', label: 'Week' },
  { id: 'day', label: 'Day' },
]

const stepName: Record<CalendarView, string> = { month: 'month', week: 'week', day: 'day' }

// Phones open on the day agenda; a seven-column month does not fit a narrow screen.
const initialView = (): CalendarView =>
  typeof window !== 'undefined' && window.matchMedia?.('(max-width: 767px)').matches ? 'day' : 'month'

export function DoctorCalendarPage() {
  const [appointments, setAppointments] = useState<AppointmentDto[]>([])
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [schedule, setSchedule] = useState<DoctorScheduleDto | 'unavailable' | null>(null)
  const [view, setView] = useState<CalendarView>(initialView)
  const [cursor, setCursor] = useState(() => startOfDay(new Date()))
  const [openId, setOpenId] = useState<string | null>(null)
  const [message, setMessage] = useState('')
  const triggerRef = useRef<HTMLElement | null>(null)

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      const { data } = await threePortalApi.getDoctorAppointments()
      setAppointments(data)
      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [])

  useEffect(() => {
    void load()
    // Working hours only decorate the day view, so they never hold the calendar back.
    doctorWorkspaceApi.getSchedule().then(({ data }) => setSchedule(data)).catch(() => setSchedule('unavailable'))
  }, [load])

  const today = dayKey(new Date())
  const selectedKey = dayKey(cursor)
  const byDay = useMemo(() => groupByDay(appointments), [appointments])
  const selectedDay = byDay.get(selectedKey) ?? []
  const openAppointment = openId ? appointments.find((appointment) => appointment.id === openId) ?? null : null

  const metrics = useMemo(() => {
    const monthPrefix = selectedKey.slice(0, 7)
    return {
      today: (byDay.get(today) ?? []).filter(isActive).length,
      pending: appointments.filter((appointment) => appointment.status === 'Requested').length,
      month: appointments.filter((appointment) => isActive(appointment) && dayKey(new Date(appointment.startsAt)).startsWith(monthPrefix)).length,
    }
  }, [appointments, byDay, selectedKey, today])

  const monthLabel = selectedKey.slice(0, 7) === today.slice(0, 7) ? 'This month' : cursor.toLocaleDateString(undefined, { month: 'long' })

  const blockedToday = useMemo(() => {
    if (!schedule || schedule === 'unavailable') return []
    return schedule.blocked.filter((item) => dayKey(new Date(item.startsAt)) <= selectedKey && selectedKey <= dayKey(new Date(item.endsAt)))
  }, [schedule, selectedKey])

  const workingHours = schedule && schedule !== 'unavailable' ? workingHoursFor(cursor, schedule.windows) : null

  const open = (appointment: AppointmentDto, trigger: HTMLElement) => {
    triggerRef.current = trigger
    setOpenId(appointment.id)
  }

  const close = useCallback(() => {
    setOpenId(null)
    triggerRef.current?.focus()
  }, [])

  const onUpdated = (updated: AppointmentDto, text: string) => {
    setAppointments((previous) => previous.map((appointment) => (appointment.id === updated.id ? updated : appointment)))
    setMessage(text)
  }

  const calendar = view === 'month'
    ? <MonthGrid cursor={cursor} today={today} byDay={byDay} onSelect={setCursor} />
    : view === 'week'
      ? <WeekGrid cursor={cursor} today={today} byDay={byDay} onSelect={setCursor} onOpen={open} />
      : (
        <>
          <p className="dcal-hours">
            {schedule === null && 'Loading working hours…'}
            {schedule === 'unavailable' && 'Working hours could not be loaded.'}
            {workingHours && (workingHours.length > 0 ? `Working hours (clinic time): ${workingHours.join(', ')}` : 'No working hours set for this day.')}
          </p>
          <DayTimeline appointments={selectedDay} blocked={blockedToday} onOpen={open} />
        </>
      )

  return (
    <div className="dcal" data-view={view}>
      <header className="dcal-header">
        <div className="dcal-heading">
          <h1>My Calendar</h1>
          <p>Manage appointments and availability</p>
        </div>
        <Link to="/doctor-profile" className="button button--secondary dcal-manage">Manage availability</Link>
      </header>

      <dl className="dcal-metrics" aria-label="Appointment summary">
        <div><dt>Today's visits</dt><dd>{status === 'ready' ? metrics.today : '–'}</dd></div>
        <div><dt>Pending requests</dt><dd>{status === 'ready' ? metrics.pending : '–'}</dd></div>
        <div><dt>{monthLabel}</dt><dd>{status === 'ready' ? metrics.month : '–'}</dd></div>
      </dl>

      {message && (
        <div className="dcal-toast" role="status">
          <span>{message}</span>
          <button type="button" className="dcal-icon-btn" aria-label="Dismiss message" onClick={() => setMessage('')}>×</button>
        </div>
      )}

      <div className="dcal-body">
        <section className="dcal-main" aria-label="Calendar">
          <div className="dcal-toolbar">
            <h2 className="dcal-title" aria-live="polite">{rangeTitle(cursor, view)}</h2>
            <div className="dcal-controls">
              <div className="dcal-seg" role="group" aria-label="Calendar view">
                {views.map((item) => (
                  <button key={item.id} type="button" aria-pressed={view === item.id} className={view === item.id ? 'dcal-seg-btn dcal-seg-btn--on' : 'dcal-seg-btn'} onClick={() => setView(item.id)}>
                    {item.label}
                  </button>
                ))}
              </div>
              <div className="dcal-nav">
                <button type="button" className="dcal-nav-btn" aria-label={`Previous ${stepName[view]}`} onClick={() => setCursor(shiftByView(cursor, view, -1))}>‹</button>
                <button type="button" className="dcal-nav-btn dcal-nav-btn--today" onClick={() => setCursor(startOfDay(new Date()))}>Today</button>
                <button type="button" className="dcal-nav-btn" aria-label={`Next ${stepName[view]}`} onClick={() => setCursor(shiftByView(cursor, view, 1))}>›</button>
              </div>
            </div>
          </div>

          {status === 'error' && <ErrorState message="Your appointments could not be loaded. Nothing was changed." onRetry={() => void load()} />}
          {status === 'loading' && (
            <div className="dcal-skeleton" role="status" aria-live="polite">
              <span className="sr-only">Loading your calendar</span>
              {Array.from({ length: 4 }, (_, index) => <span key={index} className="dcal-skeleton-row" />)}
            </div>
          )}
          {status === 'ready' && (
            <>
              {view === 'day' && <DateStrip cursor={cursor} today={today} byDay={byDay} onSelect={setCursor} />}
              <div key={`${view}-${view === 'day' ? selectedKey : ''}`} className="dcal-view">{calendar}</div>
            </>
          )}
        </section>

        {view !== 'day' && <aside className="dcal-side" aria-label="Selected day">
          <h2 className="dcal-side-title">Selected day</h2>
          <p className="dcal-side-date">
            {formatLongDay(cursor)}
            {status === 'ready' && <span> · {selectedDay.length} {selectedDay.length === 1 ? 'appointment' : 'appointments'}</span>}
          </p>
          {status === 'loading' && <div className="dcal-skeleton" aria-hidden="true"><span className="dcal-skeleton-row" /><span className="dcal-skeleton-row" /></div>}
          {status === 'error' && <p className="dcal-empty">Appointments are unavailable.</p>}
          {status === 'ready' && (
            <div key={selectedKey} className="dcal-view">
              <DayTimeline appointments={selectedDay} onOpen={open} />
            </div>
          )}
        </aside>}
      </div>

      {openAppointment && <AppointmentDrawer key={openAppointment.id} appointment={openAppointment} onClose={close} onUpdated={onUpdated} />}
    </div>
  )
}
